//! 🧪️ Existing checkpoint pins match an independent BLAKE3 commitment under original bounded events.
use super::*;
#[test]
fn original_existing_checkpoint_hashes_actual_rows_authors_message_and_ordered_pins(){let f:serde_json::Value=serde_json::from_str(include_str!("existing.json")).unwrap();let mut changes=ArtifactHistoryLedger::new();for row in f["changes"].as_array().unwrap(){changes.try_push(Change{id:row["id"].as_str().unwrap().into(),edit_ids:row["editIds"].as_array().unwrap().iter().map(|s|s.as_str().unwrap().into()).collect(),description:row["description"].as_str().map(str::to_owned),saved_at:row["savedAt"].as_str().unwrap().into()}).unwrap();}let checkpoint=Checkpoint{id:"original".into(),parent_id:Some(f["parent"].as_str().unwrap().into()),change_ids:f["changeIds"].as_array().unwrap().iter().map(|s|s.as_str().unwrap().into()).collect(),authors:f["authors"].as_array().unwrap().iter().map(|s|Author{id:s.as_str().unwrap().into(),name:"unused name".into(),avatar:None}).collect(),message:Some(f["message"].as_str().unwrap().into()),timestamp:f["timestamp"].as_str().unwrap().into(),composition_pins:Vec::new()};let pins:Vec<_>=f["pins"].as_array().unwrap().iter().map(|p|CompositionPin{child_ref:semio_framework_artifact_reference::ArtifactRef{artifact_id:p["id"].as_str().unwrap().into(),dialect:semio_framework_artifact_reference::ArtifactDialect{artifact_kind:p["kind"].as_str().unwrap().into(),standard:p["standard"].as_str().unwrap().into(),subset:p["subset"].as_str().unwrap().into()}},checkpoint_id:p["checkpoint"].as_str().unwrap().into()}).collect();let input=OriginalCheckpointIdentityInput{generation:31,checkpoint:&checkpoint,changes:&changes,pins:&pins};let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:1};let cuts:Vec<_>=f["cuts"].as_array().unwrap().iter().map(|n|Some(n.as_u64().unwrap()as usize)).chain([None]).collect();for cut in cuts{let mut owner=OriginalCheckpointIdentity::default();for step in 0..100000{if cut==Some(step)||owner.digest().is_some(){break}let d=owner.demands();assert!(d.copy_bytes<=4096);for axis in 0..3{let mut denied=grant;match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes=d.copy_bytes-1,_=>denied.maximum_depth=0};let(p,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.advance(&input,denied).unwrap());assert_eq!(p,Default::default());assert_eq!((h.requested_bytes,h.released_bytes),(0,0));}let(p,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.advance(&input,grant).unwrap());assert!(p.fits(grant));assert_eq!((h.requested_bytes,h.released_bytes),(0,0));assert!(step<99999);}if cut.is_none(){assert_eq!(owner.digest().unwrap().iter().map(|byte|format!("{byte:02x}")).collect::<String>(),f["digest"].as_str().unwrap());}if !owner.terminal_is_empty(){let foreign=OriginalCheckpointIdentityInput{generation:32,..input};let(error,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.advance(&foreign,grant).unwrap_err());assert_eq!(error.retained_progress(),Default::default());assert_eq!((h.requested_bytes,h.released_bytes),(0,0));let(p,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.close_step(grant));assert!(p.fits(grant));assert_eq!((h.requested_bytes,h.released_bytes),(0,0));}assert!(owner.terminal_is_empty());}let reversed:Vec<_>=pins.iter().rev().cloned().collect();let unordered=OriginalCheckpointIdentityInput{pins:&reversed,..input};let mut owner=OriginalCheckpointIdentity::default();assert!(owner.advance(&unordered,grant).is_err());owner.close_step(grant);while changes.pop().is_some(){} }
